<template><SuperAdminLayout><header><h1>{{cfg.title}}</h1><small>Report Date: {{today}} · Prepared By: System Administrator</small></header><section class="filters"><input v-model="search" placeholder="Search customer, user, or IP"/><button @click="load">Search</button><button @click="print">Print</button></section><section class="summary"><div v-for="(value,key) in data.summary||{}" :key="key"><span>{{key.replaceAll('_',' ')}}</span><strong>{{value}}</strong></div></section><section class="table"><table><thead><tr><th v-for="col in cfg.cols" :key="col">{{col.replaceAll('_',' ')}}</th></tr></thead><tbody><tr v-for="(row,i) in filtered" :key="i"><td v-for="col in cfg.cols" :key="col">{{row[col]??'—'}}</td></tr><tr v-if="!filtered.length"><td :colspan="cfg.cols.length">No records found.</td></tr></tbody></table></section></SuperAdminLayout></template>
<script setup>import{computed,onMounted,ref}from'vue';import{useRoute}from'vue-router';import SuperAdminLayout from'../components/SuperAdminLayout.vue';import client from'../api/client';const route=useRoute(),search=ref(''),data=ref({}),today=new Date().toLocaleDateString();const configs={status:{title:'12.4 Customer Account Status Report',url:'/super-admin/reports/account-status',cols:['customer_no','company','status','plan','since','last_activity','balance','country','payment_status']},login:{title:'12.5 Login / Logout History Report',url:'/super-admin/reports/login-history',cols:['date','time','customer_no','company','user','role','event','status','ip','device','country']},users:{title:'12.6 Users Monitoring Report',url:'/super-admin/reports/users-monitoring',cols:['date','time','customer_no','company','user','role','activity','user_status','risk','ip','device','country']}};const cfg=computed(()=>configs[route.meta.kind]);const filtered=computed(()=>{const q=search.value.toLowerCase();return(data.value.rows||[]).filter(r=>!q||Object.values(r).join(' ').toLowerCase().includes(q))});const load=async()=>{data.value=(await client.get(cfg.value.url)).data.data||{}};const print=()=>window.print();onMounted(load)</script>
<style scoped>header{display:flex;justify-content:space-between;align-items:center;border-bottom:2px solid #072b67;padding-bottom:12px;margin-bottom:14px}h1{margin:0;color:#082a64;font-size:2rem}small{color:#27334b}.filters{display:flex;gap:10px;padding:14px;border:1px solid #d8e0ec;border-radius:7px}.filters input{flex:1;padding:10px;border:1px solid #bdc8d9;border-radius:5px}.filters button{padding:10px 18px;border:1px solid #092f69;border-radius:5px;background:#092f69;color:#fff}.summary{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin:16px 0}.summary div{border:1px solid #d8e0ec;border-left:4px solid #1266db;border-radius:7px;padding:14px}.summary span{display:block;text-transform:capitalize;font-size:.78rem}.summary strong{display:block;font-size:1.5rem;color:#082a64}.table{overflow:auto}table{min-width:1000px;width:100%;border-collapse:collapse;font-size:.8rem}th{background:#06275c;color:#fff;text-transform:capitalize}th,td{padding:10px;border:1px solid #d9e0ea;text-align:left}@media(max-width:700px){.summary{grid-template-columns:repeat(2,1fr)}header{display:block}}</style>
